const { graphqlRequest } = require('./request');
const { createPagesClient } = require('./objects/pages');
const { createBlogsClient } = require('./objects/blogs');
const { createArticlesClient } = require('./objects/articles');
const { createCollectionsClient } = require('./objects/collections');
const { createProductsClient } = require('./objects/products');
const { createMediaClient } = require('./objects/media');
const { createMenusClient } = require('./objects/menus');
const { createThemesClient } = require('./objects/themes');
const { createPlaceholderClient } = require('./objects/placeholders');
const { buildAdminGraphqlUrl } = require('./store-url');

function normalizeStoreToken(store) {
  return store.api_key || store.accessToken;
}

function createStoreClient(store, deps = {}) {
  const graphqlImpl = deps.graphqlRequest || graphqlRequest;
  const accessToken = normalizeStoreToken(store);
  const headers = {
    'X-Shopify-Access-Token': accessToken
  };

  const graphql = (query, variables) =>
    graphqlImpl(buildAdminGraphqlUrl(store), query, variables || {}, headers);

  return {
    store,
    graphql,
    pages: createPagesClient({ graphql }),
    blogs: createBlogsClient({ graphql }),
    articles: createArticlesClient({ graphql }),
    collections: createCollectionsClient({ graphql }),
    products: createProductsClient({ store }),
    media: createMediaClient({ store }),
    menus: createMenusClient({ store }),
    themes: createThemesClient({ graphql }),
    metafields: createPlaceholderClient(),
    metaobjects: createPlaceholderClient(),
    sellingPlans: createPlaceholderClient()
  };
}

module.exports = {
  createStoreClient
};
